#include "terrain_lod.h"
#include "terrain_editor_layout.h"
#include <iostream>
#include <stdexcept>
#include <set>
using namespace game;
void require(bool b,const char*m){if(!b)throw std::runtime_error(m);}
int main(){try{for(auto size:std::vector<std::array<int,2>>{{{1024,768}},{{1280,720}},{{800,600}},{{1920,1080}}}){float right=std::max(.65f,std::min(1.f,(size[1]-390.f)/398.f));float end=18+900*terrain_editor_toolbar_scale(size[0],size[1]);require(end+12<=size[0]-18-386*right+.001f,"toolbar overlaps tools panel");}terrain_mesh_data m;for(int z=0;z<=32;++z)for(int x=0;x<=32;++x){terrain_vertex v({{x*2.f-32,4,z*2.f-32}},{{0,1,0}},{{255,255,255,255}});v.editor_palette={{0,0}};v.outline_id=13;m.vertices.push_back(v);}for(int z=0;z<32;++z)for(int x=0;x<32;++x){uint16_t a=z*33+x;for(auto v:{a,uint16_t(a+33),uint16_t(a+1),uint16_t(a+1),uint16_t(a+33),uint16_t(a+34)})m.indices.push_back(v);}TerrainLodSettings s;TerrainContourConstraints c;c.bounds={{-32,-32,32,32}};TerrainLodVersion version;version.load_generation=3;version.terrain_revision=9;auto g=build_terrain_lod_generation(m,s,c,2,version);require(g.nodes.size()==5,"quadtree must reach 16-cell leaves");TerrainLodView view;view.view_projection={{.01f,0,0,0,0,.01f,0,0,0,0,.01f,0,0,0,0,1}};view.camera={{0,50,0}};view.projection_scale=500;auto a=select_terrain_lod(g,view,nullptr);require(a.items.size()==1&&a.items[0].node==0,"exact flat patch should use sparse root even nearby");require(a.triangles<2048,"selection did not save triangles");auto b=select_terrain_lod(g,view,&a);require(b.items==a.items,"stationary selection unstable");view.view_projection[12]=10;auto outside=select_terrain_lod(g,view,&b);require(outside.items.empty()&&outside.culled>0,"offscreen geometry kept");require(!terrain_lod_version_current(version,TerrainLodVersion()),"old load generation accepted");auto next=version;++next.settings_revision;require(!terrain_lod_version_current(version,next),"old settings accepted");std::cout<<"Terrain CLOD CPU checks passed: hierarchy, exact sparse near field, culling, stable selection and stale generation rejection\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
